INSERT INTO public.catalog(key,data) VALUES ('office_kit',$cat$[{"id": "d1", "name": "A Desk Without A Wobble", "note": "Four legs, all touching the floor. This was not always true.", "secs": 400, "slot": "desk", "tier": 1}, {"id": "d2", "name": "Glass Top", "note": "Shows every fingerprint. Worth it.", "secs": 2400, "slot": "desk", "tier": 2}, {"id": "d3", "name": "Walnut, Or Close Enough", "note": "Veneer. Convincing veneer. Nobody is going to check.", "secs": 14400, "slot": "desk", "tier": 3}, {"id": "d4", "name": "Actual Marble", "note": "The floor beneath it has been surveyed. It was fine. Probably.", "secs": 86400, "slot": "desk", "tier": 4}, {"id": "d5", "name": "Something Black And Seamless", "note": "No drawers. No edges. No explanation.", "secs": 518400, "slot": "desk", "tier": 5}, {"id": "c1", "name": "A Chair That Goes Up", "note": "The lever works. It has never worked before.", "secs": 700, "slot": "chair", "tier": 1}, {"id": "c2", "name": "Lumbar Support", "note": "You have opinions about it now. You share them.", "secs": 4900, "slot": "chair", "tier": 2}, {"id": "c3", "name": "The Mesh One From The Catalogue", "note": "The one everybody looked at and nobody ordered.", "secs": 34300, "slot": "chair", "tier": 3}, {"id": "c4", "name": "Leather. Reclining. Silent.", "note": "It makes no sound at all. This unsettles visitors.", "secs": 240000, "slot": "chair", "tier": 4}, {"id": "r1", "name": "A Rug, Finally", "note": "Covers the stain. Everyone knows about the stain.", "secs": 500, "slot": "rug", "tier": 1}, {"id": "r2", "name": "Something With A Pattern", "note": "Geometric. Inoffensive. Chosen by committee.", "secs": 3500, "slot": "rug", "tier": 2}, {"id": "r3", "name": "A Rug People Comment On", "note": "Two people have asked where it is from. You have not told them.", "secs": 24500, "slot": "rug", "tier": 3}, {"id": "r4", "name": "Handwoven, Allegedly", "note": "The invoice said handwoven. The invoice said a lot of things.", "secs": 171500, "slot": "rug", "tier": 4}, {"id": "w1", "name": "A Motivational Print", "note": "PERSEVERANCE. A canoe. Nobody has looked at it twice.", "secs": 1200, "slot": "art", "tier": 1}, {"id": "w2", "name": "A Framed Certificate", "note": "Completion, not achievement. The distinction is not visible from the door.", "secs": 8400, "slot": "art", "tier": 2}, {"id": "w3", "name": "An Actual Painting", "note": "Nobody knows who chose it. It has grown on everybody.", "secs": 58800, "slot": "art", "tier": 3}, {"id": "w4", "name": "The Founder Portrait", "note": "It is not Dave. Nobody will say who it is.", "secs": 411600, "slot": "art", "tier": 4}, {"id": "tv1", "slot": "tv", "tier": 1, "secs": 259200, "min_cost": 50000000}]$cat$) ON CONFLICT(key) DO UPDATE SET data=excluded.data;
INSERT INTO public.catalog(key,data) VALUES ('vanity',$cat$[{"id": "g1", "name": "A Faint Warmth", "note": "Barely there. You know it is there.", "secs": 300, "slot": "glow", "tier": 1}, {"id": "g2", "name": "Employee Of The Month Sheen", "note": "The particular gold of a laminated certificate.", "secs": 1500, "slot": "glow", "tier": 2}, {"id": "g3", "name": "Executive Blue", "note": "The colour of a screensaver in a room nobody books.", "secs": 7500, "slot": "glow", "tier": 3}, {"id": "g4", "name": "Fire Drill Red", "note": "People instinctively file toward the exit when you walk past.", "secs": 37500, "slot": "glow", "tier": 4}, {"id": "g5", "name": "Server Room Green", "note": "You hum slightly. Nobody has mentioned it.", "secs": 187500, "slot": "glow", "tier": 5}, {"id": "g6", "name": "Unapproved Purple", "note": "Not in the brand guidelines. Not addressed by the brand guidelines.", "secs": 937500, "slot": "glow", "tier": 6}, {"id": "s1", "name": "Good Posture", "note": "You are not taller. You simply take up more of the room.", "secs": 900, "slot": "size", "tier": 1}, {"id": "s2", "name": "Presence", "note": "People stop talking slightly before you arrive.", "secs": 6000, "slot": "size", "tier": 2}, {"id": "s3", "name": "Corner Office Energy", "note": "Doorways are now a consideration.", "secs": 40000, "slot": "size", "tier": 3}, {"id": "h1", "name": "A Mug You Never Wash", "note": "It has a ring in it older than most of the staff.", "secs": 450, "slot": "held", "tier": 1}, {"id": "h2", "name": "A Clipboard", "note": "You carry it everywhere. Nobody asks what is on it. That is the trick.", "secs": 2700, "slot": "held", "tier": 2}, {"id": "h3", "name": "A Briefcase With Nothing In It", "note": "Weightless. Convincing.", "secs": 16000, "slot": "held", "tier": 3}, {"id": "h4", "name": "A Trophy For Something", "note": "The plaque has been buffed smooth. Nobody remembers the category.", "secs": 96000, "slot": "held", "tier": 4}, {"id": "h5", "name": "The Golden Stapler", "note": "It does not staple. It has not stapled in years. It is beyond stapling.", "secs": 576000, "slot": "held", "tier": 5}, {"id": "a1", "name": "Perpetual Dust Motes", "note": "Lit from somewhere. There is no window on that side.", "secs": 1800, "slot": "aura", "tier": 1}, {"id": "a2", "name": "A Faint Shimmer", "note": "Facilities have inspected it twice and filed nothing.", "secs": 12000, "slot": "aura", "tier": 2}, {"id": "a3", "name": "Small Contained Flames", "note": "Signed off by nobody. Questioned by nobody.", "secs": 80000, "slot": "aura", "tier": 3}]$cat$) ON CONFLICT(key) DO UPDATE SET data=excluded.data;